The method `L` of class `Grammar` is modified to generate $Lᴸ(G) = \{\chi \in T^* | S \Rightarrow ᴸ \chi\}$ and $Lᴿ(G) = \{\chi \in T^* | S \Rightarrow ᴿ \chi\}$.

```python
from collections.abc import Iterator

class Grammar:
  def __init__(
    self, T: set[str], N: set[str], P: set[tuple[str, str]], S: str
  ):
    self.T, self.N, self.P, self.S = T, N, P, S

  def LL(self, log=False, stats=False) -> Iterator[str]:
    dd, d = set(), {self.S}
    if log:
      print('    ', self.S)
    while d != set():
      if stats:
        print('# added derivations:', len(d))
      if log:
        print()
      dd.update(d)
      d = set()
      for π in sorted(dd, key=len):
        l = min((π.find(x) for x in π.split() if x in self.N), default=len(π))
        for σ, τ in self.P:  # production σ → τ
          i = π.find(σ)
          if i != -1 and i == l:  # π == π[0:i] + σ + π[i + len(σ):]
            χ = π[0:i] + τ + π[i + len(σ) :]
            χ = χ.replace('  ', ' ')
            if (χ not in dd) and (χ not in d):
              if all(a in self.T for a in χ.split()):
                yield χ.strip()
              if log:
                print('    ', π, '⇒ᴸ', χ)
              d.add(χ)

As the symbols are characters, the implementation uses strings rather than sets of characters for the `first` sets.

```python
PlainChars = (
  ' !"#$%&\',-./0123456789:;<=>@ABCDEFGHIJKLMNO'
  + 'PQRSTUVWXYZ[]^_`abcdefghijklmnopqrstuvwxyz{}~'
)
EscapedChars = '()*+?\\|'
FirstFactor = PlainChars + '\\('

src: str
pos: int
sym: str

def nxt():
  global pos, sym
  if pos < len(src):
    sym, pos = src[pos], pos + 1
  else:
    sym = chr(0)  # end-of-input symbol

def expression():  # expression → term { '|' term }
  term()
  while sym == '|':
    nxt()
    term()

def term():  # term → factor { factor }
  factor()
  while sym in FirstFactor:
    factor()

def factor():  # factor → atom [ '*' | '+' | '?' ]
  atom()
  if sym in '*+?':
    nxt()

def atom():  # atom → plainchar | escapedchar | '(' expression ')'
  if sym in PlainChars:
    nxt()
  elif sym == '\\':
    nxt()
    if sym in EscapedChars:
      nxt()
    else:
      raise Exception('invalid escaped character at ' + str(pos))
  elif sym == '(':
    nxt()
    expression()
    if sym == ')':
      nxt()
    else:
      raise Exception("')' expected at " + str(pos))
  else:
    raise Exception('invalid character at ' + str(pos))

def parse(s: str):
  global src, pos
  src, pos = s, 0
  nxt()
  expression()
  if sym != chr(0):
    raise Exception('unexpected character at ' + str(pos))

# parse("a\$") # Exception: invalid escaped character at 3
# parse("a(b") # Exception: ')' expected at 3
# parse("a(" + chr(5) + ")") # invalid character at 3
# parse("a" + chr(5)) # unexpected character at 2
parse('(a*)*abcc')
